1	package main
2	
3	import (
4		"errors"
5		"flag"
6		"fmt"
7		"io"
8		"strings"
9	)
10	
11	// timeFmt 是命令行展示时间的格式（JSON 文件内使用 RFC3339）。
12	const timeFmt = "2006-01-02 15:04:05 -0700"
13	
14	// newFlagSet 为子命令准备统一的解析器：错误不自动退出，也不自行打印，
15	// 全部交由 parseFlags 统一输出，避免重复提示。
16	func newFlagSet(name string, _ io.Writer) *flag.FlagSet {
17		fs := flag.NewFlagSet(name, flag.ContinueOnError)
18		fs.SetOutput(io.Discard)
19		fs.Usage = func() {}
20		return fs
21	}
22	
23	// parseFlags 解析子命令参数。第二个返回值是退出码；ok=false 时应直接退出。
24	func parseFlags(fs *flag.FlagSet, argv []string, stdout, stderr io.Writer, printCmdHelp func(io.Writer)) (ok bool, code int) {
25		if err := fs.Parse(argv); err != nil {
26			if errors.Is(err, flag.ErrHelp) {
27				printCmdHelp(stdout)
28				return false, exitOK
29			}
30			fmt.Fprintf(stderr, "%s %s: %v；运行 %s %s --help 查看用法\n", appName, fs.Name(), err, appName, fs.Name())
31			return false, exitUsage
32		}
33		if fs.NArg() > 0 {
34			fmt.Fprintf(stderr, "%s %s: 未知参数 %q；运行 %s %s --help 查看用法\n", appName, fs.Name(), fs.Arg(0), appName, fs.Name())
35			return false, exitUsage
36		}
37		return true, 0
38	}
39	
40	func cmdRegister(dataFile string, argv []string, stdout, stderr io.Writer) int {
41		fs := newFlagSet("register", stderr)
42		fs.StringVar(&dataFile, "data", dataFile, "本地台账数据文件路径")
43		id := fs.String("id", "", "包裹编号（不可为空或仅含空白）")
44		station := fs.String("station", "", "收件站点（不可为空或仅含空白）")
45		if ok, code := parseFlags(fs, argv, stdout, stderr, printRegisterHelp); !ok {
46			return code
47		}
48	
49		cleanIDVal, err := cleanID("包裹编号", *id)
50		if err != nil {
51			fmt.Fprintf(stderr, "%s register: %v\n", appName, err)
52			return exitBusiness
53		}
54		cleanStation, err := cleanID("收件站点", *station)
55		if err != nil {
56			fmt.Fprintf(stderr, "%s register: %v\n", appName, err)
57			return exitBusiness
58		}
59	
60		store, err := Open(dataFile)
61		if err != nil {
62			fmt.Fprintf(stderr, "%s register: %v\n", appName, err)
63			return exitBusiness
64		}
65		p, err := store.Register(cleanIDVal, cleanStation, now())
66		if err != nil {
67			fmt.Fprintf(stderr, "%s register: %v\n", appName, err)
68			return exitBusiness
69		}
70	
71		fmt.Fprintf(stdout, `收件登记成功
72	包裹编号: %s
73	收件站点: %s
74	当前状态: %s
75	发生时间: %s
76	`, p.ID, p.Station, p.Status, p.Registered.Format(timeFmt))
77		return exitOK
78	}
