80	func cmdQuery(dataFile string, argv []string, stdout, stderr io.Writer) int {
81		fs := newFlagSet("query", stderr)
82		fs.StringVar(&dataFile, "data", dataFile, "本地台账数据文件路径")
83		id := fs.String("id", "", "要查询的包裹编号")
84		if ok, code := parseFlags(fs, argv, stdout, stderr, printQueryHelp); !ok {
85			return code
86		}
87	
88		cleanIDVal, err := cleanID("包裹编号", *id)
89		if err != nil {
90			fmt.Fprintf(stderr, "%s query: %v\n", appName, err)
91			return exitBusiness
92		}
93	
94		store, err := Open(dataFile)
95		if err != nil {
96			fmt.Fprintf(stderr, "%s query: %v\n", appName, err)
97			return exitBusiness
98		}
99		p, err := store.Query(cleanIDVal)
100		if err != nil {
101			fmt.Fprintf(stderr, "%s query: %v\n", appName, err)
102			return exitBusiness
103		}
104	
105		fmt.Fprintf(stdout, "包裹编号: %s\n当前站点: %s\n当前状态: %s\n轨迹（按提交顺序，共 %d 条）:\n",
106			p.ID, p.Station, p.Status, len(p.Trail))
107		for i, e := range p.Trail {
108			switch e.Op {
109			case "退回":
110				fmt.Fprintf(stdout, "  %d. 操作: 退回    源站: %s    目的站: %s    退回请求号: %s    原交接请求号: %s    原因: %s    时间: %s\n",
111					i+1, e.From, e.Station, e.Request, e.RefRequest, e.Reason, e.Time.Format(timeFmt))
112			case "出站":
113				fmt.Fprintf(stdout, "  %d. 操作: 出站    站点: %s    批次号: %s    配送员: %s    时间: %s\n",
114					i+1, e.Station, e.Batch, e.Courier, e.Time.Format(timeFmt))
115			case "回执":
116				if e.Result == resultFailed {
117					fmt.Fprintf(stdout, "  %d. 操作: 回执    站点: %s    批次号: %s    结果: %s    原因: %s    请求号: %s    时间: %s\n",
118						i+1, e.Station, e.Batch, e.Result, e.Reason, e.Request, e.Time.Format(timeFmt))
119				} else {
120					fmt.Fprintf(stdout, "  %d. 操作: 回执    站点: %s    批次号: %s    结果: %s    请求号: %s    时间: %s\n",
121						i+1, e.Station, e.Batch, e.Result, e.Request, e.Time.Format(timeFmt))
122				}
123			default:
124				req := e.Request
125				if req == "" {
126					req = "-"
127				}
128				fmt.Fprintf(stdout, "  %d. 操作: %s    站点: %s    请求号: %s    时间: %s\n",
129					i+1, e.Op, e.Station, req, e.Time.Format(timeFmt))
130			}
131		}
132		return exitOK
133	}
