135	func cmdHandoff(dataFile string, argv []string, stdout, stderr io.Writer) int {
136		fs := newFlagSet("handoff", stderr)
137		fs.StringVar(&dataFile, "data", dataFile, "本地台账数据文件路径")
138		request := fs.String("request", "", "交接请求号（用于去重）")
139		from := fs.String("from", "", "源站点")
140		to := fs.String("to", "", "目的站点")
141		var parcels stringList
142		fs.Var(&parcels, "parcel", "包裹编号，可重复指定；集合不可为空或含重复编号")
143		if ok, code := parseFlags(fs, argv, stdout, stderr, printHandoffHelp); !ok {
144			return code
145		}
146	
147		cleanReq, err := cleanID("请求号", *request)
148		if err != nil {
149			fmt.Fprintf(stderr, "%s handoff: %v\n", appName, err)
150			return exitBusiness
151		}
152		cleanFrom, err := cleanID("源站点", *from)
153		if err != nil {
154			fmt.Fprintf(stderr, "%s handoff: %v\n", appName, err)
155			return exitBusiness
156		}
157		cleanTo, err := cleanID("目的站点", *to)
158		if err != nil {
159			fmt.Fprintf(stderr, "%s handoff: %v\n", appName, err)
160			return exitBusiness
161		}
162		if len(parcels) == 0 {
163			fmt.Fprintf(stderr, "%s handoff: 包裹集合不可为空，至少需要一个 --parcel\n", appName)
164			return exitBusiness
165		}
166		cleanParcels := make([]string, 0, len(parcels))
167		seen := make(map[string]bool, len(parcels))
168		for _, raw := range parcels {
169			id, err := cleanID("包裹编号", raw)
170			if err != nil {
171				fmt.Fprintf(stderr, "%s handoff: %v\n", appName, err)
172				return exitBusiness
173			}
174			if seen[id] {
175				fmt.Fprintf(stderr, "%s handoff: 包裹集合中编号 %q 重复\n", appName, id)
176				return exitBusiness
177			}
178			seen[id] = true
179			cleanParcels = append(cleanParcels, id)
180		}
181		if cleanFrom == cleanTo {
182			fmt.Fprintf(stderr, "%s handoff: 源站点与目的站点不能相同（均为 %q）\n", appName, cleanFrom)
183			return exitBusiness
184		}
185	
186		store, err := Open(dataFile)
187		if err != nil {
188			fmt.Fprintf(stderr, "%s handoff: %v\n", appName, err)
189			return exitBusiness
190		}
191		result, replayed, err := store.Handoff(cleanReq, cleanFrom, cleanTo, cleanParcels, now())
192		if err != nil {
193			fmt.Fprintf(stderr, "%s handoff: %v\n", appName, err)
194			return exitBusiness
195		}
196	
197		headline := "交接成功"
198		if replayed {
199			headline = "交接成功（请求号重复提交，返回首次保存的结果，未再追加轨迹）"
200		}
201		fmt.Fprintf(stdout, "%s\n请求号: %s\n源站点: %s\n目的站点: %s\n包裹（%d 件）:\n",
202			headline, result.Request, result.From, result.To, len(result.Parcels))
203		for _, id := range result.Parcels {
204			fmt.Fprintf(stdout, "  - %s\n", id)
205		}
206		fmt.Fprintf(stdout, "发生时间: %s\n", result.Time.Format(timeFmt))
207		return exitOK
208	}
