260	// cleanParcelList 清洗并校验可重复的 --parcel 参数：逐个去除两端空白、
261	// 不可为空、集合不可为空且编号不可重复。
262	func cleanParcelList(raw []string) ([]string, error) {
263		if len(raw) == 0 {
264			return nil, fmt.Errorf("包裹集合不可为空，至少需要一个 --parcel")
265		}
266		clean := make([]string, 0, len(raw))
267		seen := make(map[string]bool, len(raw))
268		for _, v := range raw {
269			id, err := cleanID("包裹编号", v)
270			if err != nil {
271				return nil, err
272			}
273			if seen[id] {
274				return nil, fmt.Errorf("包裹集合中编号 %q 重复", id)
275			}
276			seen[id] = true
277			clean = append(clean, id)
278		}
279		return clean, nil
280	}
