371		if cleanResult != resultSigned && cleanResult != resultFailed {
372			fmt.Fprintf(stderr, "%s receipt: 回执结果只能是 %q 或 %q，得到 %q\n", appName, resultSigned, resultFailed, cleanResult)
373			return exitBusiness
