391		if err != nil {
392			fmt.Fprintf(stderr, "%s receipt: %v\n", appName, err)
393			return exitBusiness
394		}
395	
396		headline := "回执成功"
397		if replayed {
398			headline = "回执成功（请求号重复提交，返回首次保存的结果，未再追加轨迹）"
399		}
400		fmt.Fprintf(stdout, "%s\n请求号: %s\n批次号: %s\n包裹编号: %s\n结果: %s\n",
401			headline, res.Request, res.Batch, res.Parcel, res.Result)
402		if res.Result == resultFailed {
403			fmt.Fprintf(stdout, "原因: %s\n", res.Reason)
404		}
405		fmt.Fprintf(stdout, "发生时间: %s\n", res.Time.Format(timeFmt))
406		return exitOK
