449			} else {
450				fmt.Fprintf(stdout, "  - %s    已回执    结果: %s    请求号: %s    时间: %s\n",
451					pid, e.Result, e.Request, e.Time.Format(timeFmt))
452			}
453		}
454		return exitOK
