24	// 回执结果。
25	const (
26		resultSigned = "签收"
27		resultFailed = "失败"
28	)
29	
30	// Event 是包裹轨迹中的一条记录，按提交顺序追加。
31	type Event struct {
32		Op         string    `json:"op"`                   // 收件 | 交接 | 退回 | 出站 | 回执
33		Station    string    `json:"station"`              // 与该操作有关的站点（退回时为退回目的站，即原交接源站）
34		Time       time.Time `json:"time"`                 // 发生时间
35		Request    string    `json:"request,omitempty"`    // 交接/退回/回执请求号（收件、出站记录为空）
36		From       string    `json:"from,omitempty"`       // 退回源站（原交接目的站，仅退回记录有）
37		Reason     string    `json:"reason,omitempty"`     // 退回原因（仅退回记录有）或回执失败原因（仅失败回执有）
38		RefRequest string    `json:"refRequest,omitempty"` // 被退回的原交接请求号（仅退回记录有）
39		Batch      string    `json:"batch,omitempty"`      // 配送批次号（仅出站、回执记录有）
40		Courier    string    `json:"courier,omitempty"`    // 配送员（仅出站记录有）
41		Result     string    `json:"result,omitempty"`     // 回执结果：签收 | 失败（仅回执记录有）
42	}
43	
44	// Parcel 是一件包裹的台账信息。
45	type Parcel struct {
46		ID         string    `json:"id"`
47		Station    string    `json:"station"`    // 当前归属站点
48		Status     string    `json:"status"`     // 当前状态
49		Registered time.Time `json:"registered"` // 收件时间
50		Trail      []Event   `json:"trail"`      // 完整轨迹，按提交顺序排列
