82	// BatchResult 记录一次成功的配送批次出站，用于批次号去重、结果重放与批次查询。
83	// 成员按首次提交时给出的顺序保存，保存后不可修改；批次完成后批次号也不能复用。
84	type BatchResult struct {
85		Batch    string                   `json:"batch"`
86		Station  string                   `json:"station"`  // 出发站
87		Courier  string                   `json:"courier"`  // 配送员
88		Parcels  []string                 `json:"parcels"`  // 批次成员，按首次提交顺序
89		Time     time.Time                `json:"time"`     // 出站时间
90		Receipts map[string]*ReceiptEntry `json:"receipts"` // 逐件回执，按包裹编号索引（未回执的包裹不在其中）
91	}
92	
93	// Done 报告批次是否已完成（全部成员均已回执）。
94	func (b *BatchResult) Done() bool { return len(b.Receipts) == len(b.Parcels) }
95	
96	// ReceiptResult 记录一次成功的逐件回执，用于回执请求号去重与结果重放。
97	type ReceiptResult struct {
98		Request string    `json:"request"` // 回执请求号
99		Batch   string    `json:"batch"`   // 所属配送批次号
100		Parcel  string    `json:"parcel"`  // 包裹编号
101		Result  string    `json:"result"`  // 签收 | 失败
102		Reason  string    `json:"reason,omitempty"`
103		Time    time.Time `json:"time"`
104	}
105	
106	// ledgerFile 是本地数据文件的磁盘结构。
107	type ledgerFile struct {
108		Version  int                       `json:"version"`
109		Parcels  map[string]*Parcel        `json:"parcels"`
110		Handoffs map[string]*HandoffResult `json:"handoffs"`
111		Returns  map[string]*ReturnResult  `json:"returns"`
112		Batches  map[string]*BatchResult   `json:"batches"`
113		Receipts map[string]*ReceiptResult `json:"receipts"`
114	}
115	
116	// Store 是一个数据文件对应的包裹站点交接台账。
117	type Store struct {
118		path string
119		data ledgerFile
120	}
121	
122	var (
123		// ErrCorrupt 表示数据文件已存在但内容损坏，不得当作空库继续读写。
124		ErrCorrupt = errors.New("数据文件已损坏")
125		// ErrNotFound 表示包裹编号在台账中不存在。
126		ErrNotFound = errors.New("包裹不存在")
127	)
128	
129	// Open 打开（或在文件不存在时建立）一个本地台账。
130	// 文件不存在时仅初始化内存结构，真正建文件发生在首次成功保存时。
131	func Open(path string) (*Store, error) {
132		s := &Store{path: path}
133		raw, err := os.ReadFile(path)
134		if err != nil {
135			if os.IsNotExist(err) {
136				s.data = ledgerFile{Version: 1, Parcels: map[string]*Parcel{}, Handoffs: map[string]*HandoffResult{},
137					Returns: map[string]*ReturnResult{}, Batches: map[string]*BatchResult{}, Receipts: map[string]*ReceiptResult{}}
138				return s, nil
139			}
140			return nil, fmt.Errorf("读取数据文件失败: %w", err)
141		}
142		if len(bytes.TrimSpace(raw)) == 0 {
143			return nil, fmt.Errorf("%w: 文件为空", ErrCorrupt)
144		}
145		if err := json.Unmarshal(raw, &s.data); err != nil {
146			return nil, fmt.Errorf("%w: %v", ErrCorrupt, err)
147		}
148		if s.data.Version != 1 || s.data.Parcels == nil || s.data.Handoffs == nil {
149			return nil, fmt.Errorf("%w: 缺少必要字段或版本不受支持", ErrCorrupt)
150		}
151		// 早期版本的数据文件没有 returns/batches/receipts 字段：按空表处理，无需手工修改。
152		if s.data.Returns == nil {
153			s.data.Returns = map[string]*ReturnResult{}
154		}
155		if s.data.Batches == nil {
156			s.data.Batches = map[string]*BatchResult{}
157		}
158		if s.data.Receipts == nil {
159			s.data.Receipts = map[string]*ReceiptResult{}
160		}
161		for _, b := range s.data.Batches {
162			if b != nil && b.Receipts == nil {
163				b.Receipts = map[string]*ReceiptEntry{}
164			}
165		}
166		if err := s.data.validate(); err != nil {
167			return nil, err
168		}
169		return s, nil
170	}
171	
172	// validate 校验载入内容内部自洽，防止损坏数据被当作有效台账继续使用。
173	func (l *ledgerFile) validate() error {
174		for id, p := range l.Parcels {
175			if p == nil || id != p.ID || p.Station == "" || p.Status == "" || len(p.Trail) == 0 {
176				return fmt.Errorf("%w: 包裹 %q 记录不完整", ErrCorrupt, id)
177			}
178			for i, e := range p.Trail {
179				if e.Op == "" || e.Station == "" || e.Time.IsZero() {
180					return fmt.Errorf("%w: 包裹 %q 第 %d 条轨迹缺少操作、站点或发生时间", ErrCorrupt, id, i+1)
181				}
182				if e.Op == "退回" {
183					if e.Request == "" || e.Reason == "" || e.From == "" {
184						return fmt.Errorf("%w: 包裹 %q 第 %d 条退回轨迹缺少退回请求号、源站或原因", ErrCorrupt, id, i+1)
185					}
186					if _, ok := l.Handoffs[e.RefRequest]; !ok {
187						return fmt.Errorf("%w: 包裹 %q 第 %d 条退回轨迹引用了不存在的原交接 %q", ErrCorrupt, id, i+1, e.RefRequest)
188					}
189				}
190				if e.Op == "出站" {
191					if e.Batch == "" || e.Courier == "" {
192						return fmt.Errorf("%w: 包裹 %q 第 %d 条出站轨迹缺少批次号或配送员", ErrCorrupt, id, i+1)
193					}
194					if _, ok := l.Batches[e.Batch]; !ok {
195						return fmt.Errorf("%w: 包裹 %q 第 %d 条出站轨迹引用了不存在的批次 %q", ErrCorrupt, id, i+1, e.Batch)
196					}
197				}
198				if e.Op == "回执" {
199					if e.Batch == "" || e.Request == "" || (e.Result != resultSigned && e.Result != resultFailed) {
200						return fmt.Errorf("%w: 包裹 %q 第 %d 条回执轨迹缺少批次号、请求号或结果无效", ErrCorrupt, id, i+1)
201					}
202					if e.Result == resultFailed && e.Reason == "" {
203						return fmt.Errorf("%w: 包裹 %q 第 %d 条失败回执轨迹缺少原因", ErrCorrupt, id, i+1)
204					}
205					if _, ok := l.Batches[e.Batch]; !ok {
206						return fmt.Errorf("%w: 包裹 %q 第 %d 条回执轨迹引用了不存在的批次 %q", ErrCorrupt, id, i+1, e.Batch)
207					}
208				}
209			}
210		}
211		for req, h := range l.Handoffs {
212			if h == nil || req != h.Request || h.From == "" || h.To == "" || len(h.Parcels) == 0 {
213				return fmt.Errorf("%w: 请求号 %q 的交接结果不完整", ErrCorrupt, req)
214			}
215			for _, id := range h.Parcels {
216				if _, ok := l.Parcels[id]; !ok {
217					return fmt.Errorf("%w: 请求号 %q 引用了不存在的包裹 %q", ErrCorrupt, req, id)
218				}
219			}
220			if h.ReturnedBy != "" {
221				r, ok := l.Returns[h.ReturnedBy]
222				if !ok || r.Handoff != req {
223					return fmt.Errorf("%w: 交接 %q 标记的退回请求号 %q 无法对应", ErrCorrupt, req, h.ReturnedBy)
224				}
225			}
226		}
227		for req, r := range l.Returns {
228			if r == nil || req != r.Request || r.Handoff == "" || r.From == "" || r.To == "" ||
229				r.Reason == "" || len(r.Parcels) == 0 || r.Time.IsZero() {
230				return fmt.Errorf("%w: 退回请求号 %q 的退回结果不完整", ErrCorrupt, req)
231			}
232			h, ok := l.Handoffs[r.Handoff]
233			if !ok {
234				return fmt.Errorf("%w: 退回请求号 %q 引用了不存在的原交接 %q", ErrCorrupt, req, r.Handoff)
235			}
236			if h.ReturnedBy != req || r.From != h.To || r.To != h.From || !sameSet(r.Parcels, h.Parcels) {
237				return fmt.Errorf("%w: 退回请求号 %q 与原交接 %q 的记录不一致", ErrCorrupt, req, r.Handoff)
238			}
239			for _, id := range r.Parcels {
240				if _, ok := l.Parcels[id]; !ok {
241					return fmt.Errorf("%w: 退回请求号 %q 引用了不存在的包裹 %q", ErrCorrupt, req, id)
242				}
243			}
244		}
245		for id, b := range l.Batches {
246			if b == nil || id != b.Batch || b.Station == "" || b.Courier == "" || len(b.Parcels) == 0 || b.Time.IsZero() {
247				return fmt.Errorf("%w: 批次号 %q 的出站结果不完整", ErrCorrupt, id)
248			}
249			seen := make(map[string]bool, len(b.Parcels))
250			for _, pid := range b.Parcels {
251				if seen[pid] {
252					return fmt.Errorf("%w: 批次 %q 的成员 %q 重复", ErrCorrupt, id, pid)
253				}
254				seen[pid] = true
255				if _, ok := l.Parcels[pid]; !ok {
256					return fmt.Errorf("%w: 批次 %q 引用了不存在的包裹 %q", ErrCorrupt, id, pid)
257				}
258			}
259			for pid, e := range b.Receipts {
260				if e == nil || !seen[pid] || e.Request == "" || e.Time.IsZero() ||
261					(e.Result != resultSigned && e.Result != resultFailed) ||
262					(e.Result == resultFailed && e.Reason == "") || (e.Result == resultSigned && e.Reason != "") {
263					return fmt.Errorf("%w: 批次 %q 中包裹 %q 的回执记录不完整", ErrCorrupt, id, pid)
264				}
265				rc, ok := l.Receipts[e.Request]
266				if !ok || rc.Batch != id || rc.Parcel != pid {
267					return fmt.Errorf("%w: 批次 %q 中包裹 %q 的回执请求号 %q 无法对应", ErrCorrupt, id, pid, e.Request)
268				}
269			}
270		}
271		for req, rc := range l.Receipts {
272			if rc == nil || req != rc.Request || rc.Batch == "" || rc.Parcel == "" || rc.Time.IsZero() ||
273				(rc.Result != resultSigned && rc.Result != resultFailed) ||
274				(rc.Result == resultFailed && rc.Reason == "") || (rc.Result == resultSigned && rc.Reason != "") {
275				return fmt.Errorf("%w: 回执请求号 %q 的回执结果不完整", ErrCorrupt, req)
276			}
277			b, ok := l.Batches[rc.Batch]
278			if !ok {
279				return fmt.Errorf("%w: 回执请求号 %q 引用了不存在的批次 %q", ErrCorrupt, req, rc.Batch)
280			}
281			e, ok := b.Receipts[rc.Parcel]
282			if !ok || e.Request != req || e.Result != rc.Result || e.Reason != rc.Reason || !e.Time.Equal(rc.Time) {
283				return fmt.Errorf("%w: 回执请求号 %q 与批次 %q 的回执记录不一致", ErrCorrupt, req, rc.Batch)
284			}
285		}
286		return nil
287	}
