289	// Register 执行单件收件登记并将结果整体落盘。
290	func (s *Store) Register(id, station string, now time.Time) (*Parcel, error) {
291		if _, ok := s.data.Parcels[id]; ok {
292			return nil, fmt.Errorf("包裹编号 %q 已登记，不能重复登记", id)
293		}
294		p := &Parcel{
295			ID:         id,
296			Station:    station,
297			Status:     statusInStation,
298			Registered: now,
299			Trail: []Event{{
300				Op:      "收件",
301				Station: station,
302				Time:    now,
303			}},
304		}
305		s.data.Parcels[id] = p
306		if err := s.save(); err != nil {
307			delete(s.data.Parcels, id) // 落盘失败：回滚内存变更，保留原有有效数据
308			return nil, err
309		}
310		return p, nil
311	}
