313	// Query 返回一件包裹的当前归属、状态和完整轨迹；不存在时返回 ErrNotFound。
314	func (s *Store) Query(id string) (*Parcel, error) {
315		p, ok := s.data.Parcels[id]
316		if !ok {
317			return nil, fmt.Errorf("%w: %q", ErrNotFound, id)
318		}
319		return p, nil
320	}
