322	// Handoff 提交一次多件包裹的站点交接。
323	//
324	// 首次提交：所有包裹必须已登记且当前归属源站点，否则整次失败、不作任何改动；
325	// 全部满足时一起改归目的站点并各追加一条交接记录，作为一个整体保存。
326	// 相同请求号且业务内容（源、目的、包裹集合，与顺序无关）相同：直接返回首次结果，
327	// 返回值 replayed 为 true；相同请求号但业务内容不同：报冲突，已有结果不变。
328	func (s *Store) Handoff(request, from, to string, parcels []string, now time.Time) (result *HandoffResult, replayed bool, err error) {
329		if saved, ok := s.data.Handoffs[request]; ok {
330			if saved.From == from && saved.To == to && sameSet(saved.Parcels, parcels) {
331				return saved, true, nil
332			}
333			return nil, false, fmt.Errorf("请求号 %q 已用于一次不同的交接（源=%q 目的=%q），内容冲突", request, saved.From, saved.To)
334		}
335	
336		// 首次提交：先做全部校验，任何一件不满足都整体失败。
337		for _, id := range parcels {
338			p, ok := s.data.Parcels[id]
339			if !ok {
340				return nil, false, fmt.Errorf("交接失败：包裹 %q 未登记，整次交接未执行", id)
341			}
342			if p.Station != from {
343				return nil, false, fmt.Errorf("交接失败：包裹 %q 当前归属 %q，不属于源站点 %q，整次交接未执行", id, p.Station, from)
344			}
345			if p.Status != statusInStation {
346				return nil, false, fmt.Errorf("交接失败：包裹 %q 当前状态为 %q，不是在站，整次交接未执行", id, p.Status)
347			}
348		}
349	
350		res := &HandoffResult{
351			Request: request,
352			From:    from,
353			To:      to,
354			Parcels: append([]string(nil), parcels...),
355			Time:    now,
356		}
357		s.data.Handoffs[request] = res
358	
359		// 记录旧值，落盘失败时整体回滚。
360		prev := make(map[string]struct {
361			station string
362			trail   []Event
363		}, len(parcels))
364		for _, id := range parcels {
365			p := s.data.Parcels[id]
366			prev[id] = struct {
367				station string
368				trail   []Event
369			}{p.Station, append([]Event(nil), p.Trail...)}
370			p.Station = to
371			p.Status = statusInStation
372			p.Trail = append(p.Trail, Event{
373				Op:      "交接",
374				Station: to,
375				Request: request,
376				Time:    now,
377			})
378		}
379	
380		if err := s.save(); err != nil {
381			delete(s.data.Handoffs, request)
382			for id, old := range prev {
383				p := s.data.Parcels[id]
384				p.Station = old.station
385				p.Trail = old.trail
386			}
387			return nil, false, err
388		}
389		return res, false, nil
390	}
391	
392	// Return 按原交接整批退回：实物送回该交接的源站点，批次与站点取自原交接结果。
393	//
394	// 首次退回：原交接必须存在且尚未成功退回；批次中每件包裹必须仍归属原交接目的站、
395	// 状态为在站，且最后一条流转记录就是该原交接（请求重放不产生新流转，不影响判定）。
396	// 任一条件不满足则整批拒绝，不作任何改动。全部满足时整批改归原交接源站（仍为在站），
397	// 每件按批次顺序追加一条退回记录，原收件、交接轨迹保留不变。
398	// 相同退回请求号且原交接、原因相同：直接返回首次结果，replayed 为 true，
399	// 即使包裹之后又被交接也不重新检查；请求号相同但原交接或原因不同：报冲突。
400	// 退回请求号与交接请求号分属独立去重范围，互不影响；失败的首次退回不占用请求号。
401	func (s *Store) Return(request, handoffReq, reason string, now time.Time) (result *ReturnResult, replayed bool, err error) {
402		if saved, ok := s.data.Returns[request]; ok {
403			if saved.Handoff == handoffReq && saved.Reason == reason {
404				return saved, true, nil
405			}
406			return nil, false, fmt.Errorf("退回请求号 %q 已用于一次不同的退回（原交接=%q 原因=%q），内容冲突",
407				request, saved.Handoff, saved.Reason)
408		}
409	
410		h, ok := s.data.Handoffs[handoffReq]
411		if !ok {
412			return nil, false, fmt.Errorf("退回失败：原交接请求号 %q 不存在", handoffReq)
413		}
414		if h.ReturnedBy != "" {
415			return nil, false, fmt.Errorf("退回失败：原交接 %q 已成功退回（退回请求号 %q），不能再次退回", handoffReq, h.ReturnedBy)
416		}
417	
418		// 先做全部校验，任何一件不满足都整批拒绝。
419		for _, id := range h.Parcels {
420			p, ok := s.data.Parcels[id]
421			if !ok {
422				return nil, false, fmt.Errorf("退回失败：包裹 %q 未登记，整批退回未执行", id)
423			}
424			if p.Station != h.To || p.Status != statusInStation {
425				return nil, false, fmt.Errorf("退回失败：包裹 %q 当前归属 %q、状态 %q，不在原交接目的站 %q 在站，整批退回未执行",
426					id, p.Station, p.Status, h.To)
427			}
428			last := p.Trail[len(p.Trail)-1]
429			if last.Op != "交接" || last.Request != handoffReq {
430				return nil, false, fmt.Errorf("退回失败：包裹 %q 在原交接 %q 之后又有新的流转，不能退回该交接，整批退回未执行",
431					id, handoffReq)
432			}
433		}
434	
435		res := &ReturnResult{
436			Request: request,
437			Handoff: handoffReq,
438			From:    h.To,
439			To:      h.From,
440			Reason:  reason,
441			Parcels: append([]string(nil), h.Parcels...),
442			Time:    now,
443		}
444		s.data.Returns[request] = res
445		h.ReturnedBy = request
446	
447		// 记录旧值，落盘失败时整体回滚。
448		prev := make(map[string]struct {
449			station string
450			trail   []Event
451		}, len(h.Parcels))
452		for _, id := range h.Parcels {
453			p := s.data.Parcels[id]
454			prev[id] = struct {
455				station string
456				trail   []Event
457			}{p.Station, append([]Event(nil), p.Trail...)}
458			p.Station = h.From
459			p.Status = statusInStation
460			p.Trail = append(p.Trail, Event{
461				Op:         "退回",
462				Station:    h.From,
463				From:       h.To,
464				Request:    request,
465				RefRequest: handoffReq,
466				Reason:     reason,
467				Time:       now,
468			})
469		}
470	
471		if err := s.save(); err != nil {
472			delete(s.data.Returns, request)
473			h.ReturnedBy = ""
474			for id, old := range prev {
475				p := s.data.Parcels[id]
476				p.Station = old.station
477				p.Trail = old.trail
478			}
479			return nil, false, err
480		}
481		return res, false, nil
482	}
483	
484	// Dispatch 提交一次配送批次出站。
485	//
486	// 首次出站：所有包裹必须已登记、当前归属出发站且状态为在站，否则整批拒绝、不作任何改动；
487	// 全部满足时整批转为“配送中”（站点仍记出发站），每件追加一条含批次、配送员和时间的
488	// 出站记录，批次成员按首次提交顺序保存且不可修改。批次号标识一次配送，完成后也不能复用：
489	// 相同批次号且站点、配送员、包裹集合（与顺序无关）相同，直接返回首次结果，replayed 为 true；
490	// 批次号相同但内容不同报冲突；失败的首次出站不占用批次号。
491	func (s *Store) Dispatch(batch, station, courier string, parcels []string, now time.Time) (result *BatchResult, replayed bool, err error) {
492		if saved, ok := s.data.Batches[batch]; ok {
493			if saved.Station == station && saved.Courier == courier && sameSet(saved.Parcels, parcels) {
494				return saved, true, nil
495			}
496			return nil, false, fmt.Errorf("批次号 %q 已用于一次不同的出站（出发站=%q 配送员=%q），内容冲突", batch, saved.Station, saved.Courier)
497		}
498	
499		// 首次出站：先做全部校验，任何一件不满足都整批拒绝。
500		for _, id := range parcels {
501			p, ok := s.data.Parcels[id]
502			if !ok {
503				return nil, false, fmt.Errorf("出站失败：包裹 %q 未登记，整批出站未执行", id)
504			}
505			if p.Station != station {
506				return nil, false, fmt.Errorf("出站失败：包裹 %q 当前归属 %q，不在出发站 %q，整批出站未执行", id, p.Station, station)
507			}
508			if p.Status != statusInStation {
509				return nil, false, fmt.Errorf("出站失败：包裹 %q 当前状态为 %q，不是在站，整批出站未执行", id, p.Status)
510			}
511		}
512	
513		res := &BatchResult{
514			Batch:    batch,
515			Station:  station,
516			Courier:  courier,
517			Parcels:  append([]string(nil), parcels...),
518			Time:     now,
519			Receipts: map[string]*ReceiptEntry{},
520		}
521		s.data.Batches[batch] = res
522	
523		// 记录旧值，落盘失败时整体回滚。
524		prev := make(map[string]struct {
525			status string
526			trail  []Event
527		}, len(parcels))
528		for _, id := range parcels {
529			p := s.data.Parcels[id]
530			prev[id] = struct {
531				status string
532				trail  []Event
533			}{p.Status, append([]Event(nil), p.Trail...)}
534			p.Status = statusDelivering // 站点不变，仍记出发站
535			p.Trail = append(p.Trail, Event{
536				Op:      "出站",
537				Station: station,
538				Batch:   batch,
539				Courier: courier,
540				Time:    now,
541			})
542		}
543	
544		if err := s.save(); err != nil {
545			delete(s.data.Batches, batch)
546			for id, old := range prev {
547				p := s.data.Parcels[id]
548				p.Status = old.status
549				p.Trail = old.trail
550			}
551			return nil, false, err
552		}
553		return res, false, nil
554	}
555	
556	// Receipt 提交一件包裹在某个配送批次下的回执。
557	//
558	// 首次回执：批次必须存在，包裹必须属于该批次、尚未在该批次回执，且当前仍在该批次
559	// 配送中；任一不满足则拒绝，不作任何改动。签收后状态为“已签收”；失败表示实物已回到
560	// 出发站，恢复“在站”，可加入新的配送批次。两种结果都保留站点并追加一条含批次、结果、
561	// 原因（失败时）、请求号和时间的回执记录；全部成员回执后批次自动完成。
562	// 相同回执请求号且批次、包裹、结果、清理后的原因相同：直接返回首次结果，replayed 为
563	// true，不重新检查当前状态，即使失败包裹已进入新批次；请求号相同但内容不同报冲突。
564	// 回执请求号与批次号、包裹编号、交接及退回请求号分属独立去重范围，允许同名；
565	// 失败的首次回执不占用请求号。
566	func (s *Store) Receipt(request, batch, parcel, result, reason string, now time.Time) (res *ReceiptResult, replayed bool, err error) {
567		if saved, ok := s.data.Receipts[request]; ok {
568			if saved.Batch == batch && saved.Parcel == parcel && saved.Result == result && saved.Reason == reason {
569				return saved, true, nil
570			}
571			return nil, false, fmt.Errorf("回执请求号 %q 已用于一次不同的回执（批次=%q 包裹=%q 结果=%q），内容冲突",
572				request, saved.Batch, saved.Parcel, saved.Result)
573		}
574	
575		b, ok := s.data.Batches[batch]
576		if !ok {
577			return nil, false, fmt.Errorf("回执失败：批次号 %q 不存在", batch)
578		}
579		member := false
580		for _, id := range b.Parcels {
581			if id == parcel {
582				member = true
583				break
584			}
585		}
586		if !member {
587			return nil, false, fmt.Errorf("回执失败：包裹 %q 不属于批次 %q", parcel, batch)
588		}
589		if _, done := b.Receipts[parcel]; done {
590			return nil, false, fmt.Errorf("回执失败：包裹 %q 在批次 %q 中已回执，每件在一个批次只能成功回执一次", parcel, batch)
591		}
592		p := s.data.Parcels[parcel] // 批次成员必已登记（载入校验保证）
593		if p.Status != statusDelivering || currentBatch(p) != batch {
594			return nil, false, fmt.Errorf("回执失败：包裹 %q 当前状态为 %q，不在批次 %q 配送中", parcel, p.Status, batch)
595		}
596	
597		res = &ReceiptResult{
598			Request: request,
599			Batch:   batch,
600			Parcel:  parcel,
601			Result:  result,
602			Reason:  reason,
603			Time:    now,
604		}
605		entry := &ReceiptEntry{Request: request, Result: result, Reason: reason, Time: now}
606	
607		// 记录旧值，落盘失败时整体回滚。
608		oldStatus, oldStation := p.Status, p.Station
609		oldTrail := append([]Event(nil), p.Trail...)
610	
611		if result == resultSigned {
612			p.Status = statusSigned // 站点保留不变
613		} else {
614			p.Status = statusInStation // 实物已回到出发站，可加入新的配送批次
615			p.Station = b.Station
616		}
617		p.Trail = append(p.Trail, Event{
618			Op:      "回执",
619			Station: p.Station,
620			Batch:   batch,
621			Result:  result,
622			Reason:  reason,
623			Request: request,
624			Time:    now,
625		})
626		b.Receipts[parcel] = entry
627		s.data.Receipts[request] = res
628	
629		if err := s.save(); err != nil {
630			delete(s.data.Receipts, request)
631			delete(b.Receipts, parcel)
632			p.Status, p.Station, p.Trail = oldStatus, oldStation, oldTrail
633			return nil, false, err
634		}
635		return res, false, nil
636	}
637	
638	// currentBatch 返回包裹当前配送中的批次号（最后一条出站记录的批次）；不在配送中返回空。
639	func currentBatch(p *Parcel) string {
640		for i := len(p.Trail) - 1; i >= 0; i-- {
641			if p.Trail[i].Op == "出站" {
642				return p.Trail[i].Batch
643			}
644		}
645		return ""
646	}
647	
648	// BatchQuery 返回一个配送批次的出站结果与逐件回执进度；批次不存在时报错。
649	func (s *Store) BatchQuery(batch string) (*BatchResult, error) {
650		b, ok := s.data.Batches[batch]
651		if !ok {
652			return nil, fmt.Errorf("批次 %q 不存在", batch)
653		}
654		return b, nil
655	}
656	
657	// sameSet 判断两个包裹列表作为集合是否相同（顺序不影响判定）。
658	func sameSet(a, b []string) bool {
659		if len(a) != len(b) {
660			return false
661		}
662		x := append([]string(nil), a...)
663		y := append([]string(nil), b...)
664		sort.Strings(x)
665		sort.Strings(y)
666		for i := range x {
667			if x[i] != y[i] {
668				return false
669			}
670		}
671		return true
672	}
673	
674	// save 将当前台账作为一个整体原子写入数据文件：先写临时文件并同步，
675	// 校验可重新解析后再原子替换，最后目录同步，避免保存失败留下部分业务变更。
676	func (s *Store) save() error {
677		if err := os.MkdirAll(filepath.Dir(s.path), 0o755); err != nil {
678			return fmt.Errorf("保存数据文件失败: %w", err)
679		}
680		buf, err := json.MarshalIndent(s.data, "", "  ")
681		if err != nil {
682			return fmt.Errorf("保存数据文件失败: %w", err)
683		}
684		buf = append(buf, '\n')
685	
686		tmp, err := os.CreateTemp(filepath.Dir(s.path), ".parcelhub-*.tmp")
687		if err != nil {
688			return fmt.Errorf("保存数据文件失败: %w", err)
689		}
690		tmpName := tmp.Name()
691		cleanup := func() { _ = os.Remove(tmpName) }
692	
693		if _, err := tmp.Write(buf); err != nil {
694			_ = tmp.Close()
695			cleanup()
696			return fmt.Errorf("保存数据文件失败: %w", err)
697		}
698		if err := tmp.Sync(); err != nil {
699			_ = tmp.Close()
700			cleanup()
701			return fmt.Errorf("保存数据文件失败: %w", err)
702		}
703		if err := tmp.Close(); err != nil {
704			cleanup()
705			return fmt.Errorf("保存数据文件失败: %w", err)
706		}
707	
708		// 替换前确认临时文件自身可解析，杜绝把损坏内容写到正式位置。
709		var check ledgerFile
710		if err := json.Unmarshal(buf, &check); err != nil {
711			cleanup()
712			return fmt.Errorf("保存数据文件失败: 写入内容无效: %w", err)
713		}
714	
715		if err := os.Rename(tmpName, s.path); err != nil {
716			cleanup()
717			return fmt.Errorf("保存数据文件失败: %w", err)
718		}
719		if dir, err := os.Open(filepath.Dir(s.path)); err == nil {
720			_ = dir.Sync()
721			_ = dir.Close()
722		}
723		return nil
724	}
725

file.content:
package main

import (
	"bytes"
	"encoding/json"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"time"
)

// 包裹状态。
const (
	// statusInStation 表示包裹当前在某站点（已收件、已完成交接或回执失败回到出发站）。
	statusInStation = "在站"
	// statusDelivering 表示包裹已随某个配送批次出站，正在配送中。
	statusDelivering = "配送中"
	// statusSigned 表示包裹已签收（回执结果为签收）。
	statusSigned = "已签收"
)

// 回执结果。
const (
	resultSigned = "签收"
	resultFailed = "失败"
)

// Event 是包裹轨迹中的一条记录，按提交顺序追加。
type Event struct {
	Op         string    `json:"op"`                   // 收件 | 交接 | 退回 | 出站 | 回执
	Station    string    `json:"station"`              // 与该操作有关的站点（退回时为退回目的站，即原交接源站）
	Time       time.Time `json:"time"`                 // 发生时间
	Request    string    `json:"request,omitempty"`    // 交接/退回/回执请求号（收件、出站记录为空）
	From       string    `json:"from,omitempty"`       // 退回源站（原交接目的站，仅退回记录有）
	Reason     string    `json:"reason,omitempty"`     // 退回原因（仅退回记录有）或回执失败原因（仅失败回执有）
	RefRequest string    `json:"refRequest,omitempty"` // 被退回的原交接请求号（仅退回记录有）
	Batch      string    `json:"batch,omitempty"`      // 配送批次号（仅出站、回执记录有）
	Courier    string    `json:"courier,omitempty"`    // 配送员（仅出站记录有）
	Result     string    `json:"result,omitempty"`     // 回执结果：签收 | 失败（仅回执记录有）
}

// Parcel 是一件包裹的台账信息。
type Parcel struct {
	ID         string    `json:"id"`
	Station    string    `json:"station"`    // 当前归属站点
	Status     string    `json:"status"`     // 当前状态
	Registered time.Time `json:"registered"` // 收件时间
	Trail      []Event   `json:"trail"`      // 完整轨迹，按提交顺序排列
}

// HandoffResult 记录一次成功交接，用于请求号去重与结果重放。
type HandoffResult struct {
	Request    string    `json:"request"`
	From       string    `json:"from"`
	To         string    `json:"to"`
	Parcels    []string  `json:"parcels"` // 按首次提交时给出的顺序保存
	Time       time.Time `json:"time"`
	ReturnedBy string    `json:"returnedBy,omitempty"` // 已成功退回该交接的退回请求号（未退回为空）
}

// ReturnResult 记录一次成功的整批退回，用于退回请求号去重与结果重放。
type ReturnResult struct {
	Request string    `json:"request"` // 退回请求号
	Handoff string    `json:"handoff"` // 被退回的原交接请求号
	From    string    `json:"from"`    // 退回源站（原交接目的站）
	To      string    `json:"to"`      // 退回目的站（原交接源站）
	Reason  string    `json:"reason"`
	Parcels []string  `json:"parcels"` // 原交接批次，按原交接保存的顺序
	Time    time.Time `json:"time"`
}

// ReceiptEntry 是批次内一件包裹的回执记录。
type ReceiptEntry struct {
	Request string    `json:"request"`          // 回执请求号
	Result  string    `json:"result"`           // 签收 | 失败
	Reason  string    `json:"reason,omitempty"` // 失败原因（仅失败回执有）
	Time    time.Time `json:"time"`
}

// BatchResult 记录一次成功的配送批次出站，用于批次号去重、结果重放与批次查询。
// 成员按首次提交时给出的顺序保存，保存后不可修改；批次完成后批次号也不能复用。
type BatchResult struct {
	Batch    string                   `json:"batch"`
	Station  string                   `json:"station"`  // 出发站
	Courier  string                   `json:"courier"`  // 配送员
	Parcels  []string                 `json:"parcels"`  // 批次成员，按首次提交顺序
	Time     time.Time                `json:"time"`     // 出站时间
	Receipts map[string]*ReceiptEntry `json:"receipts"` // 逐件回执，按包裹编号索引（未回执的包裹不在其中）
}

// Done 报告批次是否已完成（全部成员均已回执）。
func (b *BatchResult) Done() bool { return len(b.Receipts) == len(b.Parcels) }

// ReceiptResult 记录一次成功的逐件回执，用于回执请求号去重与结果重放。
type ReceiptResult struct {
	Request string    `json:"request"` // 回执请求号
	Batch   string    `json:"batch"`   // 所属配送批次号
	Parcel  string    `json:"parcel"`  // 包裹编号
	Result  string    `json:"result"`  // 签收 | 失败
	Reason  string    `json:"reason,omitempty"`
	Time    time.Time `json:"time"`
}

// ledgerFile 是本地数据文件的磁盘结构。
type ledgerFile struct {
	Version  int                       `json:"version"`
	Parcels  map[string]*Parcel        `json:"parcels"`
	Handoffs map[string]*HandoffResult `json:"handoffs"`
	Returns  map[string]*ReturnResult  `json:"returns"`
	Batches  map[string]*BatchResult   `json:"batches"`
	Receipts map[string]*ReceiptResult `json:"receipts"`
}

// Store 是一个数据文件对应的包裹站点交接台账。
type Store struct {
	path string
	data ledgerFile
}

var (
	// ErrCorrupt 表示数据文件已存在但内容损坏，不得当作空库继续读写。
	ErrCorrupt = errors.New("数据文件已损坏")
	// ErrNotFound 表示包裹编号在台账中不存在。
	ErrNotFound = errors.New("包裹不存在")
)

// Open 打开（或在文件不存在时建立）一个本地台账。
// 文件不存在时仅初始化内存结构，真正建文件发生在首次成功保存时。
func Open(path string) (*Store, error) {
	s := &Store{path: path}
	raw, err := os.ReadFile(path)
	if err != nil {
		if os.IsNotExist(err) {
			s.data = ledgerFile{Version: 1, Parcels: map[string]*Parcel{}, Handoffs: map[string]*HandoffResult{},
				Returns: map[string]*ReturnResult{}, Batches: map[string]*BatchResult{}, Receipts: map[string]*ReceiptResult{}}
			return s, nil
		}
		return nil, fmt.Errorf("读取数据文件失败: %w", err)
	}
	if len(bytes.TrimSpace(raw)) == 0 {
		return nil, fmt.Errorf("%w: 文件为空", ErrCorrupt)
	}
	if err := json.Unmarshal(raw, &s.data); err != nil {
		return nil, fmt.Errorf("%w: %v", ErrCorrupt, err)
	}
	if s.data.Version != 1 || s.data.Parcels == nil || s.data.Handoffs == nil {
		return nil, fmt.Errorf("%w: 缺少必要字段或版本不受支持", ErrCorrupt)
	}
	// 早期版本的数据文件没有 returns/batches/receipts 字段：按空表处理，无需手工修改。
	if s.data.Returns == nil {
		s.data.Returns = map[string]*ReturnResult{}
	}
	if s.data.Batches == nil {
		s.data.Batches = map[string]*BatchResult{}
	}
	if s.data.Receipts == nil {
		s.data.Receipts = map[string]*ReceiptResult{}
	}
	for _, b := range s.data.Batches {
		if b != nil && b.Receipts == nil {
			b.Receipts = map[string]*ReceiptEntry{}
		}
	}
	if err := s.data.validate(); err != nil {
		return nil, err
	}
	return s, nil
}

// validate 校验载入内容内部自洽，防止损坏数据被当作有效台账继续使用。
func (l *ledgerFile) validate() error {
	for id, p := range l.Parcels {
		if p == nil || id != p.ID || p.Station == "" || p.Status == "" || len(p.Trail) == 0 {
			return fmt.Errorf("%w: 包裹 %q 记录不完整", ErrCorrupt, id)
		}
		for i, e := range p.Trail {
			if e.Op == "" || e.Station == "" || e.Time.IsZero() {
				return fmt.Errorf("%w: 包裹 %q 第 %d 条轨迹缺少操作、站点或发生时间", ErrCorrupt, id, i+1)
			}
			if e.Op == "退回" {
				if e.Request == "" || e.Reason == "" || e.From == "" {
					return fmt.Errorf("%w: 包裹 %q 第 %d 条退回轨迹缺少退回请求号、源站或原因", ErrCorrupt, id, i+1)
				}
				if _, ok := l.Handoffs[e.RefRequest]; !ok {
					return fmt.Errorf("%w: 包裹 %q 第 %d 条退回轨迹引用了不存在的原交接 %q", ErrCorrupt, id, i+1, e.RefRequest)
				}
			}
			if e.Op == "出站" {
				if e.Batch == "" || e.Courier == "" {
					return fmt.Errorf("%w: 包裹 %q 第 %d 条出站轨迹缺少批次号或配送员", ErrCorrupt, id, i+1)
				}
				if _, ok := l.Batches[e.Batch]; !ok {
					return fmt.Errorf("%w: 包裹 %q 第 %d 条出站轨迹引用了不存在的批次 %q", ErrCorrupt, id, i+1, e.Batch)
				}
			}
			if e.Op == "回执" {
				if e.Batch == "" || e.Request == "" || (e.Result != resultSigned && e.Result != resultFailed) {
					return fmt.Errorf("%w: 包裹 %q 第 %d 条回执轨迹缺少批次号、请求号或结果无效", ErrCorrupt, id, i+1)
				}
				if e.Result == resultFailed && e.Reason == "" {
					return fmt.Errorf("%w: 包裹 %q 第 %d 条失败回执轨迹缺少原因", ErrCorrupt, id, i+1)
				}
				if _, ok := l.Batches[e.Batch]; !ok {
					return fmt.Errorf("%w: 包裹 %q 第 %d 条回执轨迹引用了不存在的批次 %q", ErrCorrupt, id, i+1, e.Batch)
				}
			}
		}
	}
	for req, h := range l.Handoffs {
		if h == nil || req != h.Request || h.From == "" || h.To == "" || len(h.Parcels) == 0 {
			return fmt.Errorf("%w: 请求号 %q 的交接结果不完整", ErrCorrupt, req)
		}
		for _, id := range h.Parcels {
			if _, ok := l.Parcels[id]; !ok {
				return fmt.Errorf("%w: 请求号 %q 引用了不存在的包裹 %q", ErrCorrupt, req, id)
			}
		}
		if h.ReturnedBy != "" {
			r, ok := l.Returns[h.ReturnedBy]
			if !ok || r.Handoff != req {
				return fmt.Errorf("%w: 交接 %q 标记的退回请求号 %q 无法对应", ErrCorrupt, req, h.ReturnedBy)
			}
		}
	}
	for req, r := range l.Returns {
		if r == nil || req != r.Request || r.Handoff == "" || r.From == "" || r.To == "" ||
			r.Reason == "" || len(r.Parcels) == 0 || r.Time.IsZero() {
			return fmt.Errorf("%w: 退回请求号 %q 的退回结果不完整", ErrCorrupt, req)
		}
		h, ok := l.Handoffs[r.Handoff]
		if !ok {
			return fmt.Errorf("%w: 退回请求号 %q 引用了不存在的原交接 %q", ErrCorrupt, req, r.Handoff)
		}
		if h.ReturnedBy != req || r.From != h.To || r.To != h.From || !sameSet(r.Parcels, h.Parcels) {
			return fmt.Errorf("%w: 退回请求号 %q 与原交接 %q 的记录不一致", ErrCorrupt, req, r.Handoff)
		}
		for _, id := range r.Parcels {
			if _, ok := l.Parcels[id]; !ok {
				return fmt.Errorf("%w: 退回请求号 %q 引用了不存在的包裹 %q", ErrCorrupt, req, id)
			}
		}
	}
	for id, b := range l.Batches {
		if b == nil || id != b.Batch || b.Station == "" || b.Courier == "" || len(b.Parcels) == 0 || b.Time.IsZero() {
			return fmt.Errorf("%w: 批次号 %q 的出站结果不完整", ErrCorrupt, id)
		}
		seen := make(map[string]bool, len(b.Parcels))
		for _, pid := range b.Parcels {
			if seen[pid] {
				return fmt.Errorf("%w: 批次 %q 的成员 %q 重复", ErrCorrupt, id, pid)
			}
			seen[pid] = true
			if _, ok := l.Parcels[pid]; !ok {
				return fmt.Errorf("%w: 批次 %q 引用了不存在的包裹 %q", ErrCorrupt, id, pid)
			}
		}
		for pid, e := range b.Receipts {
			if e == nil || !seen[pid] || e.Request == "" || e.Time.IsZero() ||
				(e.Result != resultSigned && e.Result != resultFailed) ||
				(e.Result == resultFailed && e.Reason == "") || (e.Result == resultSigned && e.Reason != "") {
				return fmt.Errorf("%w: 批次 %q 中包裹 %q 的回执记录不完整", ErrCorrupt, id, pid)
			}
			rc, ok := l.Receipts[e.Request]
			if !ok || rc.Batch != id || rc.Parcel != pid {
				return fmt.Errorf("%w: 批次 %q 中包裹 %q 的回执请求号 %q 无法对应", ErrCorrupt, id, pid, e.Request)
			}
		}
	}
	for req, rc := range l.Receipts {
		if rc == nil || req != rc.Request || rc.Batch == "" || rc.Parcel == "" || rc.Time.IsZero() ||
			(rc.Result != resultSigned && rc.Result != resultFailed) ||
			(rc.Result == resultFailed && rc.Reason == "") || (rc.Result == resultSigned && rc.Reason != "") {
			return fmt.Errorf("%w: 回执请求号 %q 的回执结果不完整", ErrCorrupt, req)
		}
		b, ok := l.Batches[rc.Batch]
		if !ok {
			return fmt.Errorf("%w: 回执请求号 %q 引用了不存在的批次 %q", ErrCorrupt, req, rc.Batch)
		}
		e, ok := b.Receipts[rc.Parcel]
		if !ok || e.Request != req || e.Result != rc.Result || e.Reason != rc.Reason || !e.Time.Equal(rc.Time) {
			return fmt.Errorf("%w: 回执请求号 %q 与批次 %q 的回执记录不一致", ErrCorrupt, req, rc.Batch)
		}
	}
	return nil
}

// Register 执行单件收件登记并将结果整体落盘。
func (s *Store) Register(id, station string, now time.Time) (*Parcel, error) {
	if _, ok := s.data.Parcels[id]; ok {
		return nil, fmt.Errorf("包裹编号 %q 已登记，不能重复登记", id)
	}
	p := &Parcel{
		ID:         id,
		Station:    station,
		Status:     statusInStation,
		Registered: now,
		Trail: []Event{{
			Op:      "收件",
			Station: station,
			Time:    now,
		}},
	}
	s.data.Parcels[id] = p
	if err := s.save(); err != nil {
		delete(s.data.Parcels, id) // 落盘失败：回滚内存变更，保留原有有效数据
		return nil, err
	}
	return p, nil
}

// Query 返回一件包裹的当前归属、状态和完整轨迹；不存在时返回 ErrNotFound。
func (s *Store) Query(id string) (*Parcel, error) {
	p, ok := s.data.Parcels[id]
	if !ok {
		return nil, fmt.Errorf("%w: %q", ErrNotFound, id)
	}
	return p, nil
}

// Handoff 提交一次多件包裹的站点交接。
//
// 首次提交：所有包裹必须已登记且当前归属源站点，否则整次失败、不作任何改动；
// 全部满足时一起改归目的站点并各追加一条交接记录，作为一个整体保存。
// 相同请求号且业务内容（源、目的、包裹集合，与顺序无关）相同：直接返回首次结果，
// 返回值 replayed 为 true；相同请求号但业务内容不同：报冲突，已有结果不变。
func (s *Store) Handoff(request, from, to string, parcels []string, now time.Time) (result *HandoffResult, replayed bool, err error) {
	if saved, ok := s.data.Handoffs[request]; ok {
		if saved.From == from && saved.To == to && sameSet(saved.Parcels, parcels) {
			return saved, true, nil
		}
		return nil, false, fmt.Errorf("请求号 %q 已用于一次不同的交接（源=%q 目的=%q），内容冲突", request, saved.From, saved.To)
	}

	// 首次提交：先做全部校验，任何一件不满足都整体失败。
	for _, id := range parcels {
		p, ok := s.data.Parcels[id]
		if !ok {
			return nil, false, fmt.Errorf("交接失败：包裹 %q 未登记，整次交接未执行", id)
		}
		if p.Station != from {
			return nil, false, fmt.Errorf("交接失败：包裹 %q 当前归属 %q，不属于源站点 %q，整次交接未执行", id, p.Station, from)
		}
		if p.Status != statusInStation {
			return nil, false, fmt.Errorf("交接失败：包裹 %q 当前状态为 %q，不是在站，整次交接未执行", id, p.Status)
		}
	}

	res := &HandoffResult{
		Request: request,
		From:    from,
		To:      to,
		Parcels: append([]string(nil), parcels...),
		Time:    now,
	}
	s.data.Handoffs[request] = res

	// 记录旧值，落盘失败时整体回滚。
	prev := make(map[string]struct {
		station string
		trail   []Event
	}, len(parcels))
	for _, id := range parcels {
		p := s.data.Parcels[id]
		prev[id] = struct {
			station string
			trail   []Event
		}{p.Station, append([]Event(nil), p.Trail...)}
		p.Station = to
		p.Status = statusInStation
		p.Trail = append(p.Trail, Event{
			Op:      "交接",
			Station: to,
			Request: request,
			Time:    now,
		})
	}

	if err := s.save(); err != nil {
		delete(s.data.Handoffs, request)
		for id, old := range prev {
			p := s.data.Parcels[id]
			p.Station = old.station
			p.Trail = old.trail
		}
		return nil, false, err
	}
	return res, false, nil
}

// Return 按原交接整批退回：实物送回该交接的源站点，批次与站点取自原交接结果。
//
// 首次退回：原交接必须存在且尚未成功退回；批次中每件包裹必须仍归属原交接目的站、
// 状态为在站，且最后一条流转记录就是该原交接（请求重放不产生新流转，不影响判定）。
// 任一条件不满足则整批拒绝，不作任何改动。全部满足时整批改归原交接源站（仍为在站），
// 每件按批次顺序追加一条退回记录，原收件、交接轨迹保留不变。
// 相同退回请求号且原交接、原因相同：直接返回首次结果，replayed 为 true，
// 即使包裹之后又被交接也不重新检查；请求号相同但原交接或原因不同：报冲突。
// 退回请求号与交接请求号分属独立去重范围，互不影响；失败的首次退回不占用请求号。
func (s *Store) Return(request, handoffReq, reason string, now time.Time) (result *ReturnResult, replayed bool, err error) {
	if saved, ok := s.data.Returns[request]; ok {
		if saved.Handoff == handoffReq && saved.Reason == reason {
			return saved, true, nil
		}
		return nil, false, fmt.Errorf("退回请求号 %q 已用于一次不同的退回（原交接=%q 原因=%q），内容冲突",
			request, saved.Handoff, saved.Reason)
	}

	h, ok := s.data.Handoffs[handoffReq]
	if !ok {
		return nil, false, fmt.Errorf("退回失败：原交接请求号 %q 不存在", handoffReq)
	}
	if h.ReturnedBy != "" {
		return nil, false, fmt.Errorf("退回失败：原交接 %q 已成功退回（退回请求号 %q），不能再次退回", handoffReq, h.ReturnedBy)
	}

	// 先做全部校验，任何一件不满足都整批拒绝。
	for _, id := range h.Parcels {
		p, ok := s.data.Parcels[id]
		if !ok {
			return nil, false, fmt.Errorf("退回失败：包裹 %q 未登记，整批退回未执行", id)
		}
		if p.Station != h.To || p.Status != statusInStation {
			return nil, false, fmt.Errorf("退回失败：包裹 %q 当前归属 %q、状态 %q，不在原交接目的站 %q 在站，整批退回未执行",
				id, p.Station, p.Status, h.To)
		}
		last := p.Trail[len(p.Trail)-1]
		if last.Op != "交接" || last.Request != handoffReq {
			return nil, false, fmt.Errorf("退回失败：包裹 %q 在原交接 %q 之后又有新的流转，不能退回该交接，整批退回未执行",
				id, handoffReq)
		}
	}

	res := &ReturnResult{
		Request: request,
		Handoff: handoffReq,
		From:    h.To,
		To:      h.From,
		Reason:  reason,
		Parcels: append([]string(nil), h.Parcels...),
		Time:    now,
	}
	s.data.Returns[request] = res
	h.ReturnedBy = request

	// 记录旧值，落盘失败时整体回滚。
	prev := make(map[string]struct {
		station string
		trail   []Event
	}, len(h.Parcels))
	for _, id := range h.Parcels {
		p := s.data.Parcels[id]
		prev[id] = struct {
			station string
			trail   []Event
		}{p.Station, append([]Event(nil), p.Trail...)}
		p.Station = h.From
		p.Status = statusInStation
		p.Trail = append(p.Trail, Event{
			Op:         "退回",
			Station:    h.From,
			From:       h.To,
			Request:    request,
			RefRequest: handoffReq,
			Reason:     reason,
			Time:       now,
		})
	}

	if err := s.save(); err != nil {
		delete(s.data.Returns, request)
		h.ReturnedBy = ""
		for id, old := range prev {
			p := s.data.Parcels[id]
			p.Station = old.station
			p.Trail = old.trail
		}
		return nil, false, err
	}
	return res, false, nil
}

// Dispatch 提交一次配送批次出站。
//
// 首次出站：所有包裹必须已登记、当前归属出发站且状态为在站，否则整批拒绝、不作任何改动；
// 全部满足时整批转为“配送中”（站点仍记出发站），每件追加一条含批次、配送员和时间的
// 出站记录，批次成员按首次提交顺序保存且不可修改。批次号标识一次配送，完成后也不能复用：
// 相同批次号且站点、配送员、包裹集合（与顺序无关）相同，直接返回首次结果，replayed 为 true；
// 批次号相同但内容不同报冲突；失败的首次出站不占用批次号。
func (s *Store) Dispatch(batch, station, courier string, parcels []string, now time.Time) (result *BatchResult, replayed bool, err error) {
	if saved, ok := s.data.Batches[batch]; ok {
		if saved.Station == station && saved.Courier == courier && sameSet(saved.Parcels, parcels) {
			return saved, true, nil
		}
		return nil, false, fmt.Errorf("批次号 %q 已用于一次不同的出站（出发站=%q 配送员=%q），内容冲突", batch, saved.Station, saved.Courier)
	}

	// 首次出站：先做全部校验，任何一件不满足都整批拒绝。
	for _, id := range parcels {
		p, ok := s.data.Parcels[id]
		if !ok {
			return nil, false, fmt.Errorf("出站失败：包裹 %q 未登记，整批出站未执行", id)
		}
		if p.Station != station {
			return nil, false, fmt.Errorf("出站失败：包裹 %q 当前归属 %q，不在出发站 %q，整批出站未执行", id, p.Station, station)
		}
		if p.Status != statusInStation {
			return nil, false, fmt.Errorf("出站失败：包裹 %q 当前状态为 %q，不是在站，整批出站未执行", id, p.Status)
		}
	}

	res := &BatchResult{
		Batch:    batch,
		Station:  station,
		Courier:  courier,
		Parcels:  append([]string(nil), parcels...),
		Time:     now,
		Receipts: map[string]*ReceiptEntry{},
	}
	s.data.Batches[batch] = res

	// 记录旧值，落盘失败时整体回滚。
	prev := make(map[string]struct {
		status string
		trail  []Event
	}, len(parcels))
	for _, id := range parcels {
		p := s.data.Parcels[id]
		prev[id] = struct {
			status string
			trail  []Event
		}{p.Status, append([]Event(nil), p.Trail...)}
		p.Status = statusDelivering // 站点不变，仍记出发站
		p.Trail = append(p.Trail, Event{
			Op:      "出站",
			Station: station,
			Batch:   batch,
			Courier: courier,
			Time:    now,
		})
	}

	if err := s.save(); err != nil {
		delete(s.data.Batches, batch)
		for id, old := range prev {
			p := s.data.Parcels[id]
			p.Status = old.status
			p.Trail = old.trail
		}
		return nil, false, err
	}
	return res, false, nil
}

// Receipt 提交一件包裹在某个配送批次下的回执。
//
// 首次回执：批次必须存在，包裹必须属于该批次、尚未在该批次回执，且当前仍在该批次
// 配送中；任一不满足则拒绝，不作任何改动。签收后状态为“已签收”；失败表示实物已回到
// 出发站，恢复“在站”，可加入新的配送批次。两种结果都保留站点并追加一条含批次、结果、
// 原因（失败时）、请求号和时间的回执记录；全部成员回执后批次自动完成。
// 相同回执请求号且批次、包裹、结果、清理后的原因相同：直接返回首次结果，replayed 为
// true，不重新检查当前状态，即使失败包裹已进入新批次；请求号相同但内容不同报冲突。
// 回执请求号与批次号、包裹编号、交接及退回请求号分属独立去重范围，允许同名；
// 失败的首次回执不占用请求号。
func (s *Store) Receipt(request, batch, parcel, result, reason string, now time.Time) (res *ReceiptResult, replayed bool, err error) {
	if saved, ok := s.data.Receipts[request]; ok {
		if saved.Batch == batch && saved.Parcel == parcel && saved.Result == result && saved.Reason == reason {
			return saved, true, nil
		}
		return nil, false, fmt.Errorf("回执请求号 %q 已用于一次不同的回执（批次=%q 包裹=%q 结果=%q），内容冲突",
			request, saved.Batch, saved.Parcel, saved.Result)
	}

	b, ok := s.data.Batches[batch]
	if !ok {
		return nil, false, fmt.Errorf("回执失败：批次号 %q 不存在", batch)
	}
	member := false
	for _, id := range b.Parcels {
		if id == parcel {
			member = true
			break
		}
	}
	if !member {
		return nil, false, fmt.Errorf("回执失败：包裹 %q 不属于批次 %q", parcel, batch)
	}
	if _, done := b.Receipts[parcel]; done {
		return nil, false, fmt.Errorf("回执失败：包裹 %q 在批次 %q 中已回执，每件在一个批次只能成功回执一次", parcel, batch)
	}
	p := s.data.Parcels[parcel] // 批次成员必已登记（载入校验保证）
	if p.Status != statusDelivering || currentBatch(p) != batch {
		return nil, false, fmt.Errorf("回执失败：包裹 %q 当前状态为 %q，不在批次 %q 配送中", parcel, p.Status, batch)
	}

	res = &ReceiptResult{
		Request: request,
		Batch:   batch,
		Parcel:  parcel,
		Result:  result,
		Reason:  reason,
		Time:    now,
	}
	entry := &ReceiptEntry{Request: request, Result: result, Reason: reason, Time: now}

	// 记录旧值，落盘失败时整体回滚。
	oldStatus, oldStation := p.Status, p.Station
	oldTrail := append([]Event(nil), p.Trail...)

	if result == resultSigned {
		p.Status = statusSigned // 站点保留不变
	} else {
		p.Status = statusInStation // 实物已回到出发站，可加入新的配送批次
		p.Station = b.Station
	}
	p.Trail = append(p.Trail, Event{
		Op:      "回执",
		Station: p.Station,
		Batch:   batch,
		Result:  result,
		Reason:  reason,
		Request: request,
		Time:    now,
	})
	b.Receipts[parcel] = entry
	s.data.Receipts[request] = res

	if err := s.save(); err != nil {
		delete(s.data.Receipts, request)
		delete(b.Receipts, parcel)
		p.Status, p.Station, p.Trail = oldStatus, oldStation, oldTrail
		return nil, false, err
	}
	return res, false, nil
}

// currentBatch 返回包裹当前配送中的批次号（最后一条出站记录的批次）；不在配送中返回空。
func currentBatch(p *Parcel) string {
	for i := len(p.Trail) - 1; i >= 0; i-- {
		if p.Trail[i].Op == "出站" {
			return p.Trail[i].Batch
		}
	}
	return ""
}

// BatchQuery 返回一个配送批次的出站结果与逐件回执进度；批次不存在时报错。
func (s *Store) BatchQuery(batch string) (*BatchResult, error) {
	b, ok := s.data.Batches[batch]
	if !ok {
		return nil, fmt.Errorf("批次 %q 不存在", batch)
	}
	return b, nil
}

// sameSet 判断两个包裹列表作为集合是否相同（顺序不影响判定）。
func sameSet(a, b []string) bool {
	if len(a) != len(b) {
		return false
	}
	x := append([]string(nil), a...)
	y := append([]string(nil), b...)
	sort.Strings(x)
	sort.Strings(y)
	for i := range x {
		if x[i] != y[i] {
			return false
		}
	}
	return true
}

// save 将当前台账作为一个整体原子写入数据文件：先写临时文件并同步，
// 校验可重新解析后再原子替换，最后目录同步，避免保存失败留下部分业务变更。
func (s *Store) save() error {
	if err := os.MkdirAll(filepath.Dir(s.path), 0o755); err != nil {
		return fmt.Errorf("保存数据文件失败: %w", err)
	}
	buf, err := json.MarshalIndent(s.data, "", "  ")
	if err != nil {
		return fmt.Errorf("保存数据文件失败: %w", err)
	}
	buf = append(buf, '\n')

	tmp, err := os.CreateTemp(filepath.Dir(s.path), ".parcelhub-*.tmp")
	if err != nil {
		return fmt.Errorf("保存数据文件失败: %w", err)
	}
	tmpName := tmp.Name()
	cleanup := func() { _ = os.Remove(tmpName) }

	if _, err := tmp.Write(buf); err != nil {
		_ = tmp.Close()
		cleanup()
		return fmt.Errorf("保存数据文件失败: %w", err)
	}
	if err := tmp.Sync(); err != nil {
		_ = tmp.Close()
		cleanup()
		return fmt.Errorf("保存数据文件失败: %w", err)
	}
	if err := tmp.Close(); err != nil {
		cleanup()
		return fmt.Errorf("保存数据文件失败: %w", err)
	}

	// 替换前确认临时文件自身可解析，杜绝把损坏内容写到正式位置。
	var check ledgerFile
	if err := json.Unmarshal(buf, &check); err != nil {
		cleanup()
		return fmt.Errorf("保存数据文件失败: 写入内容无效: %w", err)
	}

	if err := os.Rename(tmpName, s.path); err != nil {
		cleanup()
		return fmt.Errorf("保存数据文件失败: %w", err)
	}
	if dir, err := os.Open(filepath.Dir(s.path)); err == nil {
		_ = dir.Sync()
		_ = dir.Close()
	}
	return nil
}

