88			t.Fatalf("查询不存在包裹应报错(1): code=%d err=%s", code, errText)
89		}
90	
91		// 交接：一件包裹不在源站点，整次失败，所有包裹不变。
92		_, errText, code = runCLI(t, dbPath, "handoff",
93			"--request", "RBAD", "--from", "站点A", "--to", "站点B",
