	mustUnfreeze(t, s1, "U1", "E1", "复核无异常", tClock(2026, 10, 5, 11, 0))
	mustFreeze(t, s1, "E2", "P001", "站点A", "再次冻结", tClock(2026, 10, 5, 12, 0))

	// 重新打开：状态、轨迹、异常单与去重规则不变。
	s2, err := Open(path)
	if err != nil {
		t.Fatalf("重新打开失败: %v", err)
